type Queue struct{ jobs []string }

func (q *Queue) Accept(id string) error {
	if id == "" {
		return errors.New("job id required")
	}
	q.jobs = append(q.jobs, id)
	return nil
}
func (q *Queue) Next() (string, bool) {
	if len(q.jobs) == 0 {
		return "", false
	}
	id := q.jobs[0]
	q.jobs = q.jobs[1:]
	return id, true
}

func main() {
	q := &Queue{}
	fmt.Println(q.Accept("report-1"))
	id, ok := q.Next()
	fmt.Println(id, ok)
}

