type UpperReader struct{ source io.Reader }

func (r UpperReader) Read(p []byte) (int, error) {
	n, err := r.source.Read(p)
	for i := 0; i < n; i++ {
		if p[i] >= 'a' && p[i] <= 'z' {
			p[i] -= 'a' - 'A'
		}
	}
	return n, err
}

