import (
	"context"
	"errors"
	"fmt"
	"time"
)

var ErrTemporary = errors.New("temporary failure")

func Retry(ctx context.Context, attempts int, op func() error) error {
	if attempts <= 0 || attempts > 8 {
		return errors.New("attempt limit must be 1 to 8")
	}
	for attempt := 0; attempt < attempts; attempt++ {
		if err := ctx.Err(); err != nil {
			return err
		}
		err := op()
		if err == nil || !errors.Is(err, ErrTemporary) || attempt == attempts-1 {
			return err
		}
		timer := time.NewTimer(time.Millisecond * time.Duration(1<<attempt))
		select {
		case <-ctx.Done():
			timer.Stop()
			return ctx.Err()
		case <-timer.C:
		}
	}
	return nil
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), time.Second)
	defer cancel()
	calls := 0
	err := Retry(ctx, 3, func() error {
		calls++
		if calls < 3 {
			return ErrTemporary
		}
		return nil
	})
	fmt.Println(calls, err)
}

// Output:
// 3 <nil>

